import{_ as t,c as a,o as s,ag as i}from"./chunks/framework.Ds6Eueu6.js";const u=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"master/advanced/chatter/actions/message.md","filePath":"master/advanced/chatter/actions/message.md","lastUpdated":1785850184000}'),o={name:"master/advanced/chatter/actions/message.md"};function n(r,e,l,d,c,h){return s(),a("div",null,e[0]||(e[0]=[i('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p>The <code>MessageAction</code> class is a custom FilamentPHP action designed for sending messages within the AureusERP system. It allows users to compose messages, mention other users, attach files, and notify followers.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li>Rich text message composition with <code>@</code> user mentions</li><li>Optional subject field</li><li>File attachments</li><li>Automatic notification to followers (database and email)</li></ul><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><h3 id="_1-defining-the-action" tabindex="-1">1. Defining the Action <a class="header-anchor" href="#_1-defining-the-action" aria-label="Permalink to &quot;1. Defining the Action&quot;">​</a></h3><p>The <code>MessageAction</code> is an extension of FilamentPHP&#39;s <code>Action</code> class. It provides a structured form for users to create messages with optional attachments.</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Webkul\\Chatter\\Filament\\Actions\\Chatter\\MessageAction</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MessageAction</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h3 id="_2-available-methods" tabindex="-1">2. Available Methods <a class="header-anchor" href="#_2-available-methods" aria-label="Permalink to &quot;2. Available Methods&quot;">​</a></h3><h4 id="getdefaultname-string" tabindex="-1"><code>getDefaultName(): ?string</code> <a class="header-anchor" href="#getdefaultname-string" aria-label="Permalink to &quot;`getDefaultName(): ?string`&quot;">​</a></h4><p>Returns the default name of the action (<code>message.action</code>).</p><h4 id="setresource-string-resource-self" tabindex="-1"><code>setResource(string $resource): self</code> <a class="header-anchor" href="#setresource-string-resource-self" aria-label="Permalink to &quot;`setResource(string $resource): self`&quot;">​</a></h4><p>Sets the resource associated with this action.</p><h4 id="setmessagemailview-string-mailview-self" tabindex="-1"><code>setMessageMailView(?string $mailView): self</code> <a class="header-anchor" href="#setmessagemailview-string-mailview-self" aria-label="Permalink to &quot;`setMessageMailView(?string $mailView): self`&quot;">​</a></h4><p>Sets the mail view path stored on the action (default <code>chatter::mail.message-mail</code>). Ignores empty values.</p><h4 id="getmessagemailview-string" tabindex="-1"><code>getMessageMailView(): string</code> <a class="header-anchor" href="#getmessagemailview-string" aria-label="Permalink to &quot;`getMessageMailView(): string`&quot;">​</a></h4><p>Retrieves the currently set email view.</p><h4 id="getresource-string" tabindex="-1"><code>getResource(): string</code> <a class="header-anchor" href="#getresource-string" aria-label="Permalink to &quot;`getResource(): string`&quot;">​</a></h4><p>Returns the associated resource name.</p><h3 id="_3-form-fields" tabindex="-1">3. Form Fields <a class="header-anchor" href="#_3-form-fields" aria-label="Permalink to &quot;3. Form Fields&quot;">​</a></h3><p>The message form consists of the following fields:</p><table tabindex="0"><thead><tr><th>Field Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>subject</td><td>TextInput</td><td>Optional subject for the message</td></tr><tr><td>body</td><td>RichEditor</td><td>The main content of the message, with <code>@</code> user mentions</td></tr><tr><td>attachments</td><td>FileUpload</td><td>Multiple file attachments</td></tr><tr><td>type</td><td>Hidden</td><td>Default value is <code>comment</code></td></tr></tbody></table><p>The attachments field stores files in the <code>messages-attachments</code> directory on the <code>public</code> disk, accepts images, PDFs, Word documents, Excel sheets, and plain text files, and limits each file to 10 MB.</p><h3 id="_4-actions" tabindex="-1">4. Actions <a class="header-anchor" href="#_4-actions" aria-label="Permalink to &quot;4. Actions&quot;">​</a></h3><ul><li><strong>Add Subject</strong>: Allows users to toggle the visibility of the subject field.</li><li><strong>Submit Message</strong>: Saves the message via <code>addMessage()</code>, attaches uploaded files via <code>addAttachments()</code>, and dispatches a <code>chatter.refresh</code> Livewire event to refresh the chatter panel.</li></ul><h3 id="_5-notifications" tabindex="-1">5. Notifications <a class="header-anchor" href="#_5-notifications" aria-label="Permalink to &quot;5. Notifications&quot;">​</a></h3><p>Success and error messages are displayed using Filament&#39;s notification system:</p><ul><li><strong>Success:</strong> Message successfully sent</li><li><strong>Error:</strong> Error occurred while sending message</li></ul><h3 id="_6-follower-notifications" tabindex="-1">6. Follower Notifications <a class="header-anchor" href="#_6-follower-notifications" aria-label="Permalink to &quot;6. Follower Notifications&quot;">​</a></h3><p>Once the message is created, the <code>ChatterNotificationService</code> notifies the record&#39;s followers automatically:</p><ul><li>Followers receive a Filament database notification and an email (rendered with the <code>chatter::mail.message-mail</code> view) containing the message content and a link to the record.</li><li>Users mentioned with <code>@</code> in the message body receive a dedicated mention notification and are added as followers of the record.</li><li>The message author is excluded from the notifications.</li></ul><h3 id="_7-customization" tabindex="-1">7. Customization <a class="header-anchor" href="#_7-customization" aria-label="Permalink to &quot;7. Customization&quot;">​</a></h3><h4 id="customize-attachments" tabindex="-1">Customize Attachments <a class="header-anchor" href="#customize-attachments" aria-label="Permalink to &quot;Customize Attachments&quot;">​</a></h4><p>Attachments are stored in <code>messages-attachments</code> and are linked to the message, so they can be retrieved using:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$message</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">attachments;</span></span></code></pre></div>',35)]))}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
